package com.ecommerce.product.service; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductRepository repo; public ProductController(ProductRepository r){repo=r;} record Req(@NotNull UUID vendorId,@NotBlank String name,@NotBlank String category,@NotBlank String sku,@Size(max=2000) String description,@NotNull @Positive BigDecimal price){} @GetMapping public Page<Product> list(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return repo.findByActiveTrueAndNameContainingIgnoreCase(q,PageRequest.of(Math.max(page,0),Math.min(size,100),Sort.by("createdAt").descending()));} @GetMapping("/{id}") public Product get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Product not found"));} @PostMapping public ResponseEntity<Product> create(@Valid @RequestBody Req x){Product p=new Product();p.setVendorId(x.vendorId());p.setName(x.name());p.setCategory(x.category());p.setSku(x.sku());p.setDescription(x.description());p.setPrice(x.price());return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(p));} @PutMapping("/{id}") public Product update(@PathVariable UUID id,@Valid @RequestBody Req x){Product p=get(id);p.setVendorId(x.vendorId());p.setName(x.name());p.setCategory(x.category());p.setSku(x.sku());p.setDescription(x.description());p.setPrice(x.price());return repo.save(p);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){Product p=get(id);p.setActive(false);repo.save(p);} }